function g(n){const t=new Date(n),a=t.getFullYear(),e=String(t.getMonth()+1).padStart(2,"0"),r=String(t.getDate()).padStart(2,"0");return`${a}-${e}-${r}`}function i(n){const t=new Date(n),a=t.getFullYear(),e=String(t.getMonth()+1).padStart(2,"0"),r=String(t.getDate()).padStart(2,"0"),o=String(t.getHours()).padStart(2,"0"),s=String(t.getMinutes()).padStart(2,"0");return`${a}-${e}-${r}T${o}:${s}`}function S(n){return new Date(n).toISOString()}export{i as a,g as f,S as t};
